package cl.acis.catalogos.config; import cl.acis.catalogos.exception.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.stereotype.Component;
@Component public class ActorHeaders{public record Actor(Long id,String rol){} public Actor leer(HttpServletRequest r){String i=r.getHeader("X-Usuario-Id"),rol=r.getHeader("X-Usuario-Rol");if(i==null||rol==null)throw new NoAutorizadoException("Faltan los headers X-Usuario-Id y X-Usuario-Rol");try{return new Actor(Long.valueOf(i),rol.toUpperCase());}catch(NumberFormatException e){throw new NoAutorizadoException("X-Usuario-Id no es válido");}} public void exigir(Actor a,String... roles){for(String r:roles)if(r.equals(a.rol()))return;throw new ProhibidoException("El rol no está autorizado");}}
